<section class="hero"><div class="eyebrow">[03] // ARMORY DATABASE</div><h1>Каталог экипировки_</h1><p class="lead">Предметы извлекаются из YAML-прототипов выбранного игрового форка. В карточках доступны Prototype ID, исходный файл и унаследованные компоненты, которые удалось разрешить.</p><div class="stats-row"><span class="tag"><?php echo e(number_format($totalItems)); ?> прототипов в выбранном форке</span><span class="tag"><?php echo e($source ? 'Фильтр форка активен' : 'Поиск по всем форкам'); ?></span></div></section>
<div class="panel"><div class="toolbar equipment-toolbar"><label>Поиск по названию / Prototype ID<input id="catalog-query" type="search" minlength="2" maxlength="100" placeholder="WeaponRifle, броня, граната…"></label><label>Категория<select id="catalog-category"><option value="">Все категории</option><option value="armor_head">Броня: голова</option><option value="armor_eyes">Броня: глаза</option><option value="armor_mask">Броня: маски</option><option value="armor_neck">Броня: шея</option><option value="armor_chest">Броня: нагрудник</option><option value="armor_clothing">Броня: одежда / комбинезоны</option><option value="armor_outer">Броня: верхняя одежда</option><option value="armor_belt">Разгрузки и пояса</option><option value="armor_back">Рюкзаки и спинные слоты</option><option value="armor_gloves">Перчатки</option><option value="armor_shoes">Обувь</option><option value="armor_other">Прочая броня</option><option value="weapon">Оружие</option><option value="melee">Ближний бой</option><option value="ammo">Боеприпасы</option><option value="grenade">Гранаты</option><option value="explosive">Взрывчатка</option><option value="medical">Медицина</option><option value="storage">Хранение</option><option value="tool">Инструменты</option><option value="shield">Щиты</option><option value="implant">Импланты</option><option value="equipment">Прочее</option></select></label><label>Сортировка<select id="catalog-sort"><option value="name:asc">Название А—Я</option><option value="name:desc">Название Я—А</option><option value="category:asc">Категория</option><option value="prototype_id:asc">Prototype ID</option></select></label><label class="catalog-toggle"><input id="catalog-unique" type="checkbox"> Только уникальные предметы форка</label><button class="button" id="catalog-search" type="button">Искать →</button></div><p class="muted" id="catalog-count">Каталог загружает до 60 результатов за поиск. В выбранном форке учитываются его предметы, родительские форки и базовые предметы.</p></div>
<div id="catalog-results" class="equipment-catalog-results"><div class="panel muted">Введи минимум 2 символа или выбери категорию.</div></div>
<style>
.equipment-toolbar{display:grid;grid-template-columns:minmax(180px,1fr) minmax(150px,.5fr) minmax(150px,.6fr) minmax(150px,.7fr) auto;align-items:end;gap:1rem}.catalog-toggle{display:flex;align-items:center;gap:.55rem;min-height:44px;font-size:.88rem}.catalog-toggle input{width:auto}.equipment-catalog-results{display:grid;gap:.8rem;margin-top:1rem}.equipment-card{border:1px solid var(--line,#344);padding:1rem;border-radius:10px;background:rgba(255,255,255,.02)}.equipment-card-head{display:flex;justify-content:space-between;gap:1rem;align-items:start}.equipment-card h3{margin:.1rem 0 .4rem;overflow-wrap:anywhere}.equipment-card pre{white-space:pre-wrap;overflow-wrap:anywhere;max-height:260px;overflow:auto;font-size:.8rem;background:rgba(0,0,0,.2);padding:.7rem;border-radius:6px}.equipment-card-meta{font-size:.85rem;opacity:.75;overflow-wrap:anywhere}.equipment-card-actions{display:flex;gap:.6rem;flex-wrap:wrap;margin-top:.7rem}.equipment-card a{color:inherit}.equipment-sprite-frame{display:flex;align-items:center;justify-content:center;min-height:180px;margin:.8rem 0;padding:.6rem;border:1px solid var(--line,#344);background:radial-gradient(ellipse,#1b2b32,#0a1216);border-radius:8px}.equipment-sprite{display:block;width:112px;height:112px;object-fit:contain;image-rendering:pixelated;filter:drop-shadow(0 3px 5px #0008)}.sprite-preview{margin:.8rem 0}.equipment-card pre{color:var(--text,#d4e6e6);line-height:1.6}@media(max-width:650px){.equipment-toolbar{grid-template-columns:1fr}.equipment-card-head{flex-direction:column}}
</style>
<script>
(() => {
 const endpoint=<?php echo json_encode(route('equipment-items.search'), 15, 512) ?>; const query=document.getElementById('catalog-query'); const category=document.getElementById('catalog-category'); const sort=document.getElementById('catalog-sort'); const unique=document.getElementById('catalog-unique'); const count=document.getElementById('catalog-count'); const results=document.getElementById('catalog-results'); const button=document.getElementById('catalog-search');
 const labels={armor:'Прочая броня',armor_head:'Броня: голова',armor_eyes:'Броня: глаза',armor_mask:'Броня: маски',armor_neck:'Броня: шея',armor_chest:'Броня: нагрудник',armor_clothing:'Броня: одежда / комбинезоны',armor_outer:'Броня: верхняя одежда',armor_belt:'Разгрузки и пояса',armor_back:'Рюкзаки и спинные слоты',armor_gloves:'Перчатки',armor_shoes:'Обувь',armor_other:'Прочая броня',weapon:'Оружие',melee:'Ближний бой',ammo:'Боеприпасы',grenade:'Гранаты',explosive:'Взрывчатка',medical:'Медицина',storage:'Хранение',tool:'Инструменты',shield:'Щиты',implant:'Импланты',equipment:'Прочее'};
 function summary(item){const parts=Array.isArray(item.humanized_stats)?item.humanized_stats:[];if(item.slots?.length)parts.push('Слоты экипировки: '+item.slots.join(', '));if(item.tags?.length)parts.push('Теги предмета: '+item.tags.join(', '));return [...new Set(parts)].join('\n');}
 function card(item){const el=document.createElement('article');el.className='equipment-card';const head=document.createElement('div');head.className='equipment-card-head';const titleBox=document.createElement('div');const h=document.createElement('h3');h.textContent=item.name;const id=document.createElement('div');id.className='equipment-card-meta';id.textContent=item.prototype_id+' · '+(item.source_name||item.source_fork);titleBox.append(h,id);const badge=document.createElement('span');badge.className='tag';badge.textContent=labels[item.category]||item.category;head.append(titleBox,badge);el.append(head);if(item.sprite_views){const views=item.sprite_views;const panel=document.createElement('div');panel.className='sprite-preview';const frame=document.createElement('div');frame.className='equipment-sprite-frame';const img=document.createElement('img');img.className='equipment-sprite';img.alt='Спрайт предмета: '+item.name;img.loading='lazy';const urls=(views.item||[]).filter(x=>typeof x==='string'&&!x.endsWith('/meta.json'));let index=0;function next(){if(index>=urls.length){img.removeAttribute('src');return;}img.src=urls[index++];}img.addEventListener('error',next);if(urls.length)next();else img.alt='Спрайт предмета не найден';frame.append(img);panel.append(frame);el.append(panel);}if(item.description){const d=document.createElement('p');d.textContent=item.description;el.append(d);}const s=summary(item);if(s){const pre=document.createElement('pre');pre.textContent=s;el.append(pre);}const file=document.createElement('div');file.className='equipment-card-meta';file.textContent=item.source_file||'';el.append(file);const actions=document.createElement('div');actions.className='equipment-card-actions';if(item.source_url){const a=document.createElement('a');a.href=item.source_url;a.target='_blank';a.rel='noopener';a.textContent='Исходный YAML ↗';actions.append(a);}const copy=document.createElement('button');copy.type='button';copy.className='button button-outline';copy.textContent='Скопировать ID';copy.addEventListener('click',async()=>{try{await navigator.clipboard.writeText(item.prototype_id);copy.textContent='Скопировано ✓';}catch(e){copy.textContent=item.prototype_id;}});actions.append(copy);el.append(actions);return el;}
 async function search(){const q=query.value.trim();const cat=category.value;if(q.length<2&&!cat){results.replaceChildren();count.textContent='Введи минимум 2 символа или выбери категорию.';const empty=document.createElement('div');empty.className='panel muted';empty.textContent='Введи минимум 2 символа или выбери категорию.';results.append(empty);return;}results.textContent='Загрузка каталога…';try{const url=new URL(endpoint,window.location.origin);if(q)url.searchParams.set('q',q);if(cat)url.searchParams.set('category',cat);const [sortBy,direction]=sort.value.split(':');url.searchParams.set('sort',sortBy);url.searchParams.set('direction',direction);if(unique.checked)url.searchParams.set('unique_only','1');const response=await fetch(url,{headers:{Accept:'application/json'}});if(!response.ok)throw new Error('HTTP '+response.status);const data=await response.json();count.textContent='Найдено: '+(data.total??data.items.length)+'. Показано: '+(data.shown??data.items.length)+' (лимит 60).'+(unique.checked?' Уникальные для форка.':'');results.replaceChildren();if(!data.items.length){const empty=document.createElement('div');empty.className='panel muted';empty.textContent='Предметы не найдены. Проверь синхронизацию и выбранный форк.';results.append(empty);return;}data.items.forEach(item=>results.append(card(item)));}catch(e){results.textContent='Не удалось загрузить каталог. Выполни миграции и php artisan equipment:sync.';}}
 button.addEventListener('click',search);sort.addEventListener('change',search);unique.addEventListener('change',search);query.addEventListener('keydown',e=>{if(e.key==='Enter'){e.preventDefault();search();}});category.addEventListener('change',search);
})();
</script>
